#include <iostream>
#include <asio.hpp>
#include "message.pb.h"

using asio::ip::tcp;

class Session : public std::enable_shared_from_this<Session> {
public:
    Session(tcp::socket socket)
        : socket_(std::move(socket)) {}

    void start() {
        do_read();
    }

private:
    void do_read() {
        auto self(shared_from_this());
        socket_.async_read_some(asio::buffer(data_, max_length),
            [this, self](std::error_code ec, std::size_t length) {
                if (!ec) {
                    tutorial::Request request;
                    if (request.ParseFromArray(data_, length)) {
                        std::cout << "Received message: " << request.message() << std::endl;
                        do_write(request.message());
                    } else {
                        std::cerr << "Failed to parse protobuf message" << std::endl;
                    }
                }
            });
    }

    void do_write(const std::string& message) {
        tutorial::Response response;
        response.set_reply("Echo: " + message);

        auto self(shared_from_this());
        response.SerializeToArray(data_, max_length);
        asio::async_write(socket_, asio::buffer(data_, response.ByteSizeLong()),
            [this, self](std::error_code ec, std::size_t /*length*/) {
                if (!ec) {
                    do_read();
                }
            });
    }

    tcp::socket socket_;
    enum { max_length = 1024 };
    char data_[max_length];
};

class Server {
public:
    Server(asio::io_context& io_context, short port)
        : acceptor_(io_context, tcp::endpoint(tcp::v4(), port)) {
        do_accept();
    }

private:
    void do_accept() {
        acceptor_.async_accept(
            [this](std::error_code ec, tcp::socket socket) {
                if (!ec) {
                    std::make_shared<Session>(std::move(socket))->start();
                }
                do_accept();
            });
    }

    tcp::acceptor acceptor_;
};

int main(int argc, char* argv[]) {
    try {
        if (argc != 2) {
            std::cerr << "Usage: tcp_server <port>\n";
            return 1;
        }

        asio::io_context io_context;

        Server server(io_context, std::atoi(argv[1]));

        io_context.run();
    } catch (std::exception& e) {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return 0;
}
